import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../models/author.dart';import '../services/theme_controller.dart';import '../state/author_list_notifier.dart';import '../widgets/theme_button.dart';class AuthorDetailScreen extends StatelessWidget{final int id;final ThemeController themeController;const AuthorDetailScreen({super.key,required this.id,required this.themeController});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Карточка автора'),actions:[ThemeButton(controller:themeController)]),body:FutureBuilder<Author?>(future:c.read<AuthorListNotifier>().findById(id),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final a=s.data;if(a==null)return const Center(child:Text('Автор не найден'));return Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:600),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(a.fullName,style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),Text('Страна: ${a.country}'),Text('Год рождения: ${a.birthYear}'),Text('Книг: ${a.bookCount}'),Text('Статус: ${a.isDeleted?'Удалён':'Активен'}'),const SizedBox(height:16),FilledButton.icon(onPressed:()=>c.go('/authors/${a.id}/edit'),icon:const Icon(Icons.edit),label:const Text('Редактировать')),OutlinedButton(onPressed:()=>c.pop(),child:const Text('Назад'))])))));}));}
